# -*- coding: utf-8 -*-
# Compléments d'articles (lot 1) : sections ajoutées après les sections existantes, et questions-réponses supplémentaires.
EXTRA1 = {
 "diagnostics-immobiliers-obligatoires-vente": dict(sections=[
   ("Le DPE en détail", ["Le diagnostic de performance énergétique est celui qui retient le plus l'attention des acheteurs. Il estime la consommation d'énergie du logement et son impact en émissions de gaz à effet de serre, en tenant compte de l'isolation, du chauffage, de la ventilation et de l'eau chaude. Le résultat prend la forme d'une étiquette de A à G, affichée dans l'annonce. Un classement défavorable n'empêche pas de vendre, mais il pèse sur la négociation, car l'acheteur chiffre déjà les travaux à venir.", "Le DPE est établi sur l'ensemble du logement, et non pièce par pièce. Pour un appartement en copropriété, le diagnostiqueur peut s'appuyer sur des informations de l'immeuble (chauffage collectif, par exemple). Pensez donc à lui remettre les factures de chauffage, les documents de travaux d'isolation et les caractéristiques des fenêtres : plus il dispose d'éléments fiables, plus le résultat reflète la réalité du bien."]),
   ("Maison ou appartement : des dossiers différents", ["Le contenu du dossier change selon le type de bien. Une maison individuelle peut nécessiter un diagnostic d'assainissement non collectif, un diagnostic termites ou un état des risques plus détaillé, alors qu'un appartement en copropriété implique surtout le mesurage de la surface privative et des informations sur les parties communes. Dans un immeuble ancien, le syndic détient souvent des documents utiles, comme un dossier technique amiante pour les parties communes.", "Si vous vendez un lot de copropriété, demandez ces documents à votre syndic le plus tôt possible : leur récupération prend parfois quelques jours, et ils sont indispensables à l'acheteur pour comprendre l'état de l'immeuble."]),
   ("Combien cela coûte et comment choisir le diagnostiqueur", ["Le coût dépend de la surface, de l'âge du bien, de la localisation et du nombre de diagnostics à réaliser. Plutôt que de choisir le moins cher, vérifiez que le professionnel est bien certifié pour chaque diagnostic, qu'il dispose d'une assurance de responsabilité et qu'il est indépendant du vendeur et de l'agence. Demandez plusieurs devis et comparez ce qu'ils incluent : un forfait regroupant tous les diagnostics est souvent plus avantageux que des interventions séparées.", "Votre conseiller peut vous indiquer la liste exacte des diagnostics nécessaires pour votre bien et coordonner le rendez-vous avec le diagnostiqueur, afin que les documents soient prêts avant les premières visites."]),
   ("Un calendrier type", [["Avant la mise en vente : vérifier la liste des diagnostics, commander ceux qui manquent et rassembler les dates de validité ;", "Pendant les visites : tenir le dossier à disposition des acquéreurs sérieux, notamment le DPE, qui figure déjà dans l'annonce ;", "À la signature du compromis : annexer le dossier complet à la promesse de vente ;", "Avant l'acte : contrôler qu'aucun diagnostic n'est périmé et en refaire un si nécessaire."]]),
   ("Les erreurs à éviter", ["La première erreur est de commander les diagnostics au dernier moment, ce qui retarde la signature du compromis. La deuxième est d'utiliser un diagnostic dont la durée de validité est dépassée. La troisième est de ne pas lire les résultats : un diagnostic qui révèle de l'amiante, du plomb ou une installation électrique vétuste doit être anticipé, car il change la négociation et parfois le prix. En parler dès le début avec votre conseiller permet de choisir une stratégie : réaliser des travaux, ajuster le prix ou présenter clairement la situation à l'acheteur."])],
   faq=[("Les diagnostics sont-ils obligatoires pour une vente entre particuliers ?", "Oui. Les obligations d'information qui pèsent sur le vendeur s'appliquent quel que soit le mode de vente, avec ou sans agence."),
        ("Quand faut-il refaire un diagnostic ?", "Quand sa durée de validité est dépassée à la date de signature de l'acte, ou lorsque la réglementation a changé et que l'ancien document n'est plus conforme. Un conseiller vous aide à contrôler les dates.")]),

 "home-staging-mieux-vendre": dict(sections=[
   ("Pourquoi le home staging fonctionne", ["Quand on visite un logement, on n'achète pas seulement des mètres carrés : on se projette dans une vie. Un espace encombré, des objets très personnels ou une ambiance sombre empêchent cette projection et attirent l'attention sur les défauts. À l'inverse, un logement propre, clair et rangé laisse imaginer ses propres meubles et ses propres habitudes. Le home staging ne cherche pas à tromper l'acheteur : il met le bien dans sa meilleure version, comme on prépare un dossier avant un entretien."]),
   ("Pièce par pièce", [["L'entrée : c'est la première impression. Dégagez le passage, rangez les chaussures et les manteaux, ajoutez une lumière accueillante ;", "Le séjour : réduisez le nombre de meubles pour agrandir l'espace, placez le canapé face à la lumière naturelle, retirez les câbles visibles ;", "La cuisine : plans de travail dégagés, électroménager propre, joints et robinetterie impeccables ;", "Les chambres : literie neutre et repassée, rangements légers, placards à moitié vides pour montrer leur capacité ;", "La salle de bains : serviettes assorties, produits rangés, joints refaits si besoin, absence d'odeurs ;", "Les extérieurs : balcon balayé, quelques plantes, jardin tondu et allées dégagées."]]),
   ("Un budget maîtrisé", ["Le home staging n'est pas une dépense lourde. Une grande partie du travail est du temps : trier, nettoyer, ranger. Pour le reste, quelques achats ciblés suffisent : ampoules plus lumineuses, peinture, un plaid ou des coussins, des plantes. Évitez les rénovations coûteuses que l'acheteur ne valorisera pas forcément : il préfère souvent refaire la cuisine ou la salle de bains à son goût. Un conseiller vous indique, selon le marché de votre quartier, ce qui vaut la peine d'être fait et ce qu'il vaut mieux laisser en l'état."]),
   ("Les photos de l'annonce", ["Les photos sont la vitrine du bien : elles décident si l'acheteur demandera une visite. Réalisez-les en journée, lumières allumées et volets ouverts, une fois le home staging terminé. Prenez chaque pièce depuis l'angle qui montre le plus de volume, sans objets personnels au premier plan. Si le bien a un atout particulier (vue, terrasse, hauteur sous plafond, cheminée), mettez-le en avant dès la première photo."]),
   ("Préparer les visites", ["Le jour de la visite, aérez le logement, allumez les lumières, réglez la température et évitez les odeurs fortes (cuisine, tabac, animaux). Si possible, laissez les visiteurs circuler librement avec le conseiller : ils se sentiront plus à l'aise pour regarder, ouvrir les placards et poser des questions. Après chaque visite, notez les retours : ce sont des indications précieuses pour ajuster la présentation, voire le prix."])],
   faq=[("Le home staging coûte-t-il cher ?", "Pas forcément. La plus grande part est du temps passé à trier et nettoyer. Quelques achats ciblés (éclairage, peinture, textiles) suffisent souvent, pour un budget bien inférieur à celui de travaux lourds."),
        ("Faut-il faire appel à un professionnel ?", "Ce n'est pas obligatoire. Un conseiller peut déjà vous donner des recommandations simples pièce par pièce. Pour un bien haut de gamme ou difficile à valoriser, un professionnel du home staging peut aider.")]),

 "mandat-exclusif-ou-simple": dict(sections=[
   ("Comment se passe la commercialisation avec un mandat", ["Une fois le mandat signé, l'agence prépare le bien : visite de présentation, photos, rédaction de l'annonce, diffusion sur son site et sur les portails, communication auprès de ses acquéreurs en recherche. Elle organise ensuite les visites, qualifie les candidats (financement, projet, délais) et vous tient informé des retours. À réception d'une offre, elle vous aide à l'analyser : prix, conditions suspensives, calendrier, solidité du plan de financement."]),
   ("Les points communs entre les deux mandats", [["un mandat écrit, comportant les informations exigées par la loi (durée, prix, honoraires, description du bien) ;", "un prix de vente affiché et, selon les cas, une marge de négociation ;", "des honoraires dus seulement si la vente se conclut grâce à l'agence, dans les conditions du mandat ;", "un devoir d'information du professionnel envers le vendeur."]]),
   ("Dans quels cas choisir le mandat exclusif", ["Le mandat exclusif convient bien lorsque vous souhaitez un accompagnement complet et une communication maîtrisée : un seul prix, un seul discours, une seule annonce. Il est particulièrement adapté aux biens qui demandent une mise en valeur soignée (maison de caractère, bien atypique) ou lorsque vous avez peu de temps à consacrer aux visites. Il suppose de choisir une agence en laquelle vous avez confiance, et de définir ensemble des objectifs : prix, calendrier, nombre de visites attendues."]),
   ("Dans quels cas préférer le mandat simple", ["Le mandat simple peut convenir si vous souhaitez garder la main : vous pouvez continuer à chercher un acquéreur vous-même, par exemple dans votre entourage, ou confier le bien à plusieurs professionnels. Il est parfois choisi pour tester le marché ou pour un bien facile à vendre. Gardez à l'esprit que la multiplication des intermédiaires peut brouiller le message : plusieurs annonces avec des photos et des prix différents donnent une impression de désordre."]),
   ("Les questions à poser à l'agence", ["Avant de signer, demandez à l'agence comment elle compte commercialiser votre bien : nombre de visites attendues, supports de diffusion, fréquence des comptes rendus, accompagnement jusqu'à l'acte. Interrogez-la aussi sur sa connaissance du quartier et sur des ventes récentes comparables. Une agence sérieuse vous répondra précisément et mettra ses engagements par écrit."])],
   faq=[("Un mandat exclusif m'empêche-t-il de vendre moi-même ?", "Pendant la durée de l'exclusivité, le bien est confié à l'agence : les conditions précises, y compris les cas où vous trouveriez vous-même un acquéreur, figurent dans le mandat. Lisez-les attentivement avant de signer."),
        ("Combien de temps dure un mandat ?", "La durée est fixée par le mandat. Elle est généralement de quelques mois, avec des modalités de renouvellement ou de fin prévues par le contrat. Demandez-les par écrit.")]),

 "fixer-le-bon-prix-estimation": dict(sections=[
   ("Prix de marché, valeur et prix affiché", ["Trois notions se confondent souvent. La valeur d'un bien est son estimation par un professionnel, sur la base du marché. Le prix de vente est celui auquel la vente se conclut réellement, après négociation. Le prix affiché dans l'annonce est celui que vous choisissez de communiquer. Pour bien vendre, ces trois prix doivent rester proches : un prix affiché très éloigné de la valeur éloigne les acheteurs sérieux, qui comparent."]),
   ("Les critères qui font vraiment varier le prix", [["l'emplacement : rue, quartier, proximité des commerces, des transports, des écoles ;", "l'état général et les prestations : cuisine, salle de bains, chauffage, menuiseries ;", "la luminosité, l'orientation et la vue ;", "les extérieurs (balcon, terrasse, jardin) et le stationnement ;", "le diagnostic énergétique, de plus en plus déterminant ;", "pour un appartement, l'étage, la présence d'un ascenseur, l'état de l'immeuble et les charges ;", "la période de vente et la tension du marché local."]]),
   ("Pourquoi un prix trop élevé coûte cher", ["Un bien trop cher voit rapidement ses visites se raréfier. Les acheteurs sont nombreux à suivre les annonces, et un bien qui reste en ligne longtemps donne l'impression d'un problème. Le vendeur finit par baisser le prix, mais dans une position plus faible : les premières semaines, qui concentrent le plus d'intérêt, sont passées. Un prix cohérent dès le début attire davantage de visites, donne plus de poids à la négociation et peut aboutir à un meilleur résultat final."]),
   ("Comment se déroule une estimation avec un conseiller", [["un premier échange pour comprendre votre projet et votre calendrier ;", "une visite du bien, avec prise de photos et de mesures ;", "une analyse des ventes récentes de biens comparables dans le secteur ;", "une restitution : fourchette de prix, stratégie de commercialisation, points forts et points à améliorer ;", "un suivi : réajustement éventuel selon les retours des visiteurs."]]),
   ("Préparer son bien avant l'estimation", ["Avant la visite, rassemblez les documents utiles : titre de propriété, taxe foncière, diagnostics déjà réalisés, factures de travaux, charges de copropriété et procès-verbaux d'assemblée générale. Plus le conseiller dispose d'informations précises, plus l'estimation est fiable. N'hésitez pas à lui signaler ce qui a été amélioré récemment (fenêtres, chaudière, isolation) : ces éléments valorisent le bien."])],
   faq=[("L'estimation est-elle un engagement de vente ?", "Non. Une estimation ne vous engage à rien : elle vous donne une indication de valeur et une stratégie possible. L'engagement n'intervient qu'avec la signature d'un mandat."),
        ("Les prix des annonces voisines suffisent-ils pour fixer le prix ?", "Ils donnent une indication, mais ce sont des prix demandés, pas des prix de vente. Un conseiller s'appuie sur des ventes réellement conclues et sur les caractéristiques propres au bien.")]),

 "compromis-de-vente-points-de-vigilance": dict(sections=[
   ("Compromis, promesse unilatérale, offre d'achat : de quoi parle-t-on ?", ["Plusieurs documents peuvent précéder la vente. L'offre d'achat est une proposition de l'acheteur, qui devient engageante si le vendeur l'accepte. Le compromis de vente, appelé aussi promesse synallagmatique, engage les deux parties à conclure la vente aux conditions prévues. La promesse unilatérale engage le vendeur, tandis que l'acheteur dispose d'une option qu'il peut lever dans un délai donné. Dans tous les cas, il s'agit d'un avant-contrat : la vente est définitivement conclue par l'acte authentique signé chez le notaire."]),
   ("Les clauses à lire avec attention", [["la clause de prix et de répartition éventuelle entre le bien et le mobilier ;", "les conditions suspensives et leur durée ;", "la date prévue pour la signature de l'acte et les conséquences d'un retard ;", "la clause pénale, qui prévoit une indemnité si l'une des parties ne respecte pas son engagement ;", "les charges et taxes : qui paie quoi jusqu'à la remise des clés ;", "la date d'entrée en jouissance (remise des clés) et l'état dans lequel le bien doit être remis."]]),
   ("Le financement : un point central", ["Pour la majorité des acquéreurs, le compromis est signé avant que le prêt soit définitivement accordé. C'est le rôle de la condition suspensive : si le financement n'est pas obtenu dans le délai prévu, l'acheteur est libéré. Pour qu'elle joue, il faut déposer les demandes de prêt rapidement, auprès de plusieurs banques ou d'un courtier, et conserver les justificatifs. Une demande tardive ou incomplète peut fragiliser la protection. Si vous avez déjà un accord de principe, informez-en l'agence : cela rassure le vendeur."]),
   ("Entre compromis et acte : le calendrier", ["Après la signature, le délai de rétractation de dix jours s'ouvre pour l'acheteur d'un logement. Le notaire vérifie ensuite le dossier : titre de propriété, urbanisme, hypothèques, droits de préemption éventuels. Les banques émettent leur offre de prêt, que l'acquéreur doit respecter avant de signer. Compter environ deux à trois mois entre compromis et acte est courant, mais ce délai varie selon les dossiers. Restez joignable : le notaire peut vous demander des pièces complémentaires."]),
   ("Avant d'aller chez le notaire : la visite de contrôle", ["Quelques jours avant la signature de l'acte, effectuez une dernière visite du bien. Vérifiez qu'il est dans l'état convenu, que les équipements prévus sont toujours présents et que d'éventuels travaux promis ont été faits. C'est le moment de signaler une anomalie, avant d'avoir signé."])],
   faq=[("Qui rédige le compromis ?", "Il peut être rédigé par l'agence ou par le notaire. Dans les deux cas, vous pouvez poser vos questions et demander des précisions avant de signer."),
        ("Peut-on se rétracter après les dix jours ?", "Après le délai de rétractation, l'acheteur est engagé. Il peut renoncer sans pénalité seulement si une condition suspensive prévue au compromis n'est pas réalisée, comme le refus de prêt dans les délais.")]),
}
